The function f should return a tuple of two floats and an integer.
```python
def f(inputs):
    result = []
    for inp in inputs:
        L, R, N, points = inp
        if N > 100:
            raise ValueError("N must be between 3 and 100, inclusive.")
        if not all(-1000 <= point[0] <= 1000 and -1000 <= point[1] <= 1000 for point in points):
            raise ValueError("All X and Y coordinates must be between -1000 and 1000, inclusive.")

        total = 0.0
        valid_points = 0
        for point in points:
            X, Y = point
            if X >= L and Y >= R:
                total += X * Y
                valid_points += 1
        result.append((total / valid_points if valid_points > 0 else 0.0, valid_points, R))

    return tuple(result)
```

